import { type SynapseEnhancedHttpClient } from "../utils/http.ts";
import { ErrorCode } from "../utils/error-codes.ts";
import { SynapseAdminApi } from "../constants/api.ts";
import { handleApiResponse } from "../utils/response-formatter.ts";
import { BaseApi } from "../utils/base-api.ts";

export interface IVoiceUserPreferences {
    default_format: string;
    default_quality: string;
    auto_convert: boolean;
    max_duration_seconds: number;
    silence_detection: boolean;
    noise_cancellation: boolean;
}

export interface IVoiceUserQuota {
    used_seconds: number;
    limit_seconds: number;
    reset_at: string;
    percentage_used: number;
    is_exhausted: boolean;
}

export interface IVoiceUserConfig {
    user_id: string;
    preferences: IVoiceUserPreferences;
    quota: IVoiceUserQuota;
    features: {
        recording_enabled: boolean;
        conversion_enabled: boolean;
        premium_features: string[];
    };
}

export interface IVoiceUserStats {
    total_recordings: number;
    total_duration_seconds: number;
    average_duration_seconds: number;
    storage_used_bytes: number;
    most_used_format: string;
    last_activity: string;
}

export interface IVoiceUserApi {
    getConfig(): Promise<IVoiceUserConfig>;
    getPreferences(): Promise<IVoiceUserPreferences>;
    updatePreferences(preferences: Partial<IVoiceUserPreferences>): Promise<IVoiceUserPreferences>;
    getQuota(): Promise<IVoiceUserQuota>;
    getStats(): Promise<IVoiceUserStats>;
}

export class VoiceUserApi extends BaseApi implements IVoiceUserApi {
    private readonly endpoint = `${SynapseAdminApi.VOICE}/user`;

    public constructor(httpClient: SynapseEnhancedHttpClient) {
        super(httpClient);
    }

    /**
     * Get complete user voice configuration
     */
    public async getConfig(): Promise<IVoiceUserConfig> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                user_config?: IVoiceUserConfig;
            };
            error?: string;
        }>(this.endpoint);

        const data = handleApiResponse(response, "Failed to get user voice config");
        return data.user_config!;
    }

    /**
     * Get user voice preferences
     */
    public async getPreferences(): Promise<IVoiceUserPreferences> {
        const config = await this.getConfig();
        return config.preferences;
    }

    /**
     * Update user voice preferences
     */
    public async updatePreferences(preferences: Partial<IVoiceUserPreferences>): Promise<IVoiceUserPreferences> {
        if (!preferences || typeof preferences !== "object") {
            throw this.createError("Preferences must be a valid object", ErrorCode.INVALID_PARAM);
        }

        const response = await this.httpClient.post<{
            status: string;
            data?: {
                preferences?: IVoiceUserPreferences;
            };
            error?: string;
        }>(this.endpoint, { preferences });

        const data = handleApiResponse(response, "Failed to update voice preferences");
        return data.preferences!;
    }

    /**
     * Get user voice quota information
     */
    public async getQuota(): Promise<IVoiceUserQuota> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                quota?: IVoiceUserQuota;
            };
            error?: string;
        }>(`${this.endpoint}/quota`);

        const data = handleApiResponse(response, "Failed to get voice quota");
        return data.quota!;
    }

    /**
     * Get user voice usage statistics
     */
    public async getStats(): Promise<IVoiceUserStats> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                stats?: IVoiceUserStats;
            };
            error?: string;
        }>(`${this.endpoint}/stats`);

        const data = handleApiResponse(response, "Failed to get voice stats");
        return data.stats!;
    }

    /**
     * Check if user has exceeded their voice quota
     */
    public async hasQuotaExceeded(): Promise<boolean> {
        const quota = await this.getQuota();
        return quota.is_exhausted;
    }

    /**
     * Get remaining quota in seconds
     */
    public async getRemainingQuota(): Promise<number> {
        const quota = await this.getQuota();
        return Math.max(0, quota.limit_seconds - quota.used_seconds);
    }

    /**
     * Get quota usage percentage
     */
    public async getQuotaPercentage(): Promise<number> {
        const quota = await this.getQuota();
        return quota.percentage_used;
    }

    /**
     * Check if a specific preference is enabled
     */
    public async isPreferenceEnabled(
        preference: keyof Omit<IVoiceUserPreferences, "default_format" | "default_quality" | "max_duration_seconds">,
    ): Promise<boolean> {
        const preferences = await this.getPreferences();
        return Boolean(preferences[preference]);
    }

    /**
     * Get formatted quota information
     */
    public async getFormattedQuota(): Promise<{
        used: string;
        limit: string;
        remaining: string;
        percentage: string;
    }> {
        const quota = await this.getQuota();

        const formatDuration = (seconds: number): string => {
            const hours = Math.floor(seconds / 3600);
            const minutes = Math.floor((seconds % 3600) / 60);
            if (hours > 0) {
                return `${hours}h ${minutes}m`;
            }
            return `${minutes}m`;
        };

        return {
            used: formatDuration(quota.used_seconds),
            limit: formatDuration(quota.limit_seconds),
            remaining: formatDuration(Math.max(0, quota.limit_seconds - quota.used_seconds)),
            percentage: `${quota.percentage_used.toFixed(1)}%`,
        };
    }
}
